6	 * Canonical postcode rules for the owner pipelines, the single authority shared by the create
7	 * and update steps so both agree.
8	 *
9	 * <p>A postcode is optional. When present it must be exactly 4 digits. Each known city maps to a
10	 * region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) and each region to an inclusive 4-digit
11	 * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a present postcode must fall within its
12	 * city's region range. A city with no known region accepts any 4-digit postcode.
13	 *
14	 * <p>The city->region and region->range tables are not kept here: they are the single authority
15	 * on {@link Owner} ({@link Owner#regionForCity} and {@link Owner#regionForPostcode}), reused so
16	 * postcode validation and the region-and-hash identity cannot drift apart.
17	 */
18	final class OwnerPostcode {
19	
20	    private OwnerPostcode() {
21	    }
22	
23	    /**
24	     * Whether the given postcode is acceptable for the city. An absent (null/blank) postcode is
25	     * always acceptable — validation applies only when present. A present postcode must be 4
26	     * digits and, for a city with a known region, within that region's range; a city with no
27	     * known region accepts any 4-digit postcode.
28	     */
29	    static boolean isValid(String postcode, String city) {
30	        if (postcode == null || postcode.isBlank()) {
31	            return true;
32	        }
33	        if (!postcode.matches("[0-9]{4}")) {
34	            return false;
35	        }
36	        String region = Owner.regionForCity(city);
37	        if (region == null) {
38	            return true;
39	        }
40	        // The postcode is valid for the city exactly when its own region range matches the
41	        // city's region; regions have distinct ranges, so a mismatch (or no containing range)
42	        // is out of range.
43	        return region.equals(Owner.regionForPostcode(postcode));
44	    }
45	}
