16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.Period;
26	import java.time.temporal.ChronoUnit;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "birth_date")
60	    private LocalDate birthDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "postcode")
72	    private String postcode;
73	
74	    @Transient
75	    private Integer householdSize;
76	
77	    @Transient
78	    private boolean bulkSignupWarning;
79	
80	    @Transient
81	    private boolean possibleDuplicate;
82	
83	    @Transient
84	    private Integer possibleDuplicateOf;
85	
86	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
87	    private Set<Pet> pets;
88	
89	    public String getAddress() {
90	        return this.address;
91	    }
92	
93	    public void setAddress(String address) {
94	        this.address = address;
95	    }
96	
97	    public String getCity() {
98	        return this.city;
99	    }
100	
101	    public void setCity(String city) {
102	        this.city = city;
103	    }
104	
105	    public String getTelephone() {
106	        return this.telephone;
107	    }
108	
109	    public void setTelephone(String telephone) {
110	        this.telephone = telephone;
111	    }
112	
113	    public String getEmail() {
114	        return this.email;
115	    }
116	
117	    public void setEmail(String email) {
118	        this.email = email;
119	    }
120	
121	    public LocalDate getRegistrationDate() {
122	        return this.registrationDate;
123	    }
124	
125	    public void setRegistrationDate(LocalDate registrationDate) {
126	        this.registrationDate = registrationDate;
127	    }
128	
129	    public LocalDate getBirthDate() {
130	        return this.birthDate;
131	    }
132	
133	    public void setBirthDate(LocalDate birthDate) {
134	        this.birthDate = birthDate;
135	    }
136	
137	    public String getCustomerCode() {
138	        return this.customerCode;
139	    }
140	
141	    public void setCustomerCode(String customerCode) {
142	        this.customerCode = customerCode;
143	    }
144	
145	    public String getHouseholdId() {
146	        return this.householdId;
147	    }
148	
149	    public void setHouseholdId(String householdId) {
150	        this.householdId = householdId;
151	    }
152	
153	    /**
154	     * The number of owners in this owner's household (owners sharing its householdId, counting
155	     * this owner). Not a persisted column — populated by the owner pipelines (create and read)
156	     * that have repository access, and consumed only by {@link #getMembershipPoints()}. {@code
157	     * null} when it has not been resolved, which the points rule treats as a single-member
158	     * household.
159	     */
160	    @Transient
161	    public Integer getHouseholdSize() {
162	        return this.householdSize;
163	    }
164	
165	    public void setHouseholdSize(Integer householdSize) {
166	        this.householdSize = householdSize;
167	    }
168	
169	    public Integer getNamesakeCount() {
170	        return this.namesakeCount;
171	    }
172	
173	    public void setNamesakeCount(Integer namesakeCount) {
174	        this.namesakeCount = namesakeCount;
175	    }
176	
177	    public String getPostcode() {
178	        return this.postcode;
179	    }
180	
181	    public void setPostcode(String postcode) {
182	        this.postcode = postcode;
183	    }
184	
185	    /**
186	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
187	     * Not persisted — derived from {@link #getLastName()} and {@link #getFirstName()}.
188	     */
189	    @Transient
190	    public String getDisplayName() {
191	        return this.getLastName() + ", " + this.getFirstName();
192	    }
193	
194	    /**
195	     * The owner's initials: the upper-cased first letters of firstName and lastName,
196	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
197	     * Not persisted — derived from {@link #getFirstName()} and {@link #getLastName()}.
198	     */
199	    @Transient
200	    public String getInitials() {
201	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
202	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
203	    }
204	
205	    /**
206	     * The owner's {@link #getTelephone() telephone} formatted for humans: the stored E.164
207	     * value rewritten as the country code, a space, then the national digits grouped in threes
208	     * separated by spaces (e.g. {@code '+61 412 345 678'}). The known country codes are
209	     * {@code '+61'} (Australia) and {@code '+1'} (NANP); any other E.164 value is split with a
210	     * two-digit country code. {@code null} when no telephone is set or the value is not in E.164
211	     * form. The raw {@link #getTelephone() telephone} is left in E.164 form. Not persisted —
212	     * derived from {@link #getTelephone()}.
213	     */
214	    @Transient
215	    public String getTelephoneDisplay() {
216	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
217	            return null;
218	        }
219	        String digits = this.telephone.substring(1);
220	        int countryCodeLength = digits.startsWith("1") && !digits.startsWith("61") ? 1 : 2;
221	        if (digits.length() <= countryCodeLength) {
222	            return this.telephone;
223	        }
224	        String countryCode = digits.substring(0, countryCodeLength);
225	        String national = digits.substring(countryCodeLength);
226	        StringBuilder grouped = new StringBuilder();
227	        for (int i = 0; i < national.length(); i++) {
228	            if (i > 0 && i % 3 == 0) {
229	                grouped.append(' ');
230	            }
231	            grouped.append(national.charAt(i));
232	        }
233	        return "+" + countryCode + " " + grouped;
234	    }
235	
236	    /**
237	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
238	     * the last two digits of the {@link #getRegistrationDate() registrationDate} year
239	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}).
240	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
241	     */
242	    @Transient
243	    public String getMembershipNumber() {
244	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
245	    }
246	
247	    /**
248	     * The owner's check digit: the Luhn check digit (0-9) computed over the digits contained
249	     * in the {@link #getCustomerCode() customerCode}. Non-digit characters are ignored.
250	     * Not persisted — derived from {@link #getCustomerCode()}.
251	     */
252	    @Transient
253	    public int getCheckDigit() {
254	        int sum = 0;
255	        boolean dbl = true;
256	        String code = this.customerCode == null ? "" : this.customerCode;
257	        for (int i = code.length() - 1; i >= 0; i--) {
258	            char c = code.charAt(i);
259	            if (c < '0' || c > '9') {
260	                continue;
261	            }
262	            int d = c - '0';
263	            if (dbl) {
264	                d *= 2;
265	                if (d > 9) {
266	                    d -= 9;
267	                }
268	            }
269	            sum += d;
270	            dbl = !dbl;
271	        }
272	        return (10 - (sum % 10)) % 10;
273	    }
274	
275	    /**
276	     * The owner's membership points. Starts at {@code 0}; adds {@code 2} when an
277	     * {@link #getEmail() email} is present; adds {@code 1} when {@link #getNamesakeCount()
278	     * namesakeCount} is {@code 0}; adds {@code 2} for a household of {@code 3} or more members
279	     * ({@link #getHouseholdSize() householdSize}); adds {@code 3} for a tenure of more than
280	     * {@code 365} days since the {@link #getRegistrationDate() registration date}. Not persisted
281	     * — derived from {@link #getEmail()}, {@link #getNamesakeCount()}, {@link #getHouseholdSize()}
282	     * and {@link #getRegistrationDate()}.
283	     */
284	    @Transient
285	    public int getMembershipPoints() {
286	        int points = 0;
287	        boolean hasEmail = this.email != null && !this.email.isBlank();
288	        if (hasEmail) {
289	            points += 2;
290	        }
291	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
292	        if (uniqueName) {
293	            points += 1;
294	        }
295	        if (this.householdSize != null && this.householdSize >= 3) {
296	            points += 2;
297	        }
298	        if (this.registrationDate != null
299	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
300	            points += 3;
301	        }
302	        return points;
303	    }
304	
305	    /**
306	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()
307	     * membershipPoints}: {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
308	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more. Not persisted — derived
309	     * from {@link #getMembershipPoints()}.
310	     */
311	    @Transient
312	    public int getMembershipLevel() {
313	        int points = getMembershipPoints();
314	        if (points >= 6) {
315	            return 4;
316	        }
317	        if (points >= 4) {
318	            return 3;
319	        }
320	        if (points >= 2) {
321	            return 2;
322	        }
323	        return 1;
324	    }
325	
326	    /**
327	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
328	     */
329	    private static final Map<String, String> CITY_REGION = Map.of(
330	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
331	
332	    /**
333	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
334	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
335	     */
336	    private static final Map<String, int[]> REGION_RANGE = Map.of(
337	        "NSW", new int[] {2000, 2099},
338	        "VIC", new int[] {3000, 3099},
339	        "QLD", new int[] {4000, 4099});
340	
341	    /**
342	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
343	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
344	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
345	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
346	     * the owner's {@link #getCustomerCode() customerCode}, so the create pipeline and
347	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
348	     * by the owner pipelines (e.g. postcode validation) rather than copied.
349	     */
350	    public static String regionFor(String postcode, String city) {
351	        String region = regionForPostcode(postcode);
352	        if (region != null) {
353	            return region;
354	        }
355	        String cityRegion = regionForCity(city);
356	        return cityRegion != null ? cityRegion : "UNKNOWN";
357	    }
358	
359	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
360	     * Brisbane->QLD), or {@code null} when the city has no known region. */
361	    public static String regionForCity(String city) {
362	        return city == null ? null : CITY_REGION.get(city);
363	    }
364	
365	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
366	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
367	     * range. */
368	    public static String regionForPostcode(String postcode) {
369	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
370	            return null;
371	        }
372	        int value = Integer.parseInt(postcode);
373	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
374	            int[] range = entry.getValue();
375	            if (value >= range[0] && value <= range[1]) {
376	                return entry.getKey();
377	            }
378	        }
379	        return null;
380	    }
381	
382	    /**
383	     * The owner's locality: the REGION prefix of the {@link #getCustomerCode() customerCode}
384	     * (the portion before the first {@code '-'}), which the create pipeline derives from the
385	     * postcode-and-city region. {@code 'UNKNOWN'} when no customerCode is set. Not persisted —
386	     * derived from {@link #getCustomerCode()}.
387	     */
388	    @Transient
389	    public String getLocality() {
390	        if (this.customerCode == null) {
391	            return "UNKNOWN";
392	        }
393	        int dash = this.customerCode.indexOf('-');
394	        return dash <= 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
395	    }
396	
397	    /**
398	     * Whether more than 80 owners had already been created today when this response was
399	     * built. Not persisted — populated for the response by the create and fetch pipelines
400	     * and defaults to {@code false} so every owner serialization carries the flag.
401	     */
402	    @Transient
403	    public boolean isBulkSignupWarning() {
404	        return this.bulkSignupWarning;
405	    }
406	
407	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
408	        this.bulkSignupWarning = bulkSignupWarning;
409	    }
410	
411	    /**
412	     * Whether this owner is a possible (soft) duplicate: not a hard duplicate, but shares an
413	     * existing owner's last name and postcode with a different telephone. Not persisted —
414	     * populated for the response by the create and fetch pipelines and defaults to
415	     * {@code false} so every owner serialization carries the flag.
416	     */
417	    @Transient
418	    public boolean isPossibleDuplicate() {
419	        return this.possibleDuplicate;
420	    }
421	
422	    public void setPossibleDuplicate(boolean possibleDuplicate) {
423	        this.possibleDuplicate = possibleDuplicate;
424	    }
425	
426	    /**
427	     * The id of the existing owner this owner possibly duplicates (shared last name and
428	     * postcode, different telephone), or {@code null} when it is not a possible duplicate.
429	     * Not persisted — populated for the response alongside {@link #isPossibleDuplicate()}.
430	     */
431	    @Transient
432	    public Integer getPossibleDuplicateOf() {
433	        return this.possibleDuplicateOf;
434	    }
435	
436	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
437	        this.possibleDuplicateOf = possibleDuplicateOf;
438	    }
439	
440	    /**
441	     * The owner's preferred contact channel: {@code 'EMAIL'} when an {@link #getEmail() email}
442	     * is present, otherwise {@code 'PHONE'}.
443	     * Not persisted — derived from {@link #getEmail()}.
444	     */
445	    @Transient
446	    public String getContactPreference() {
447	        boolean hasEmail = this.email != null && !this.email.isBlank();
448	        return hasEmail ? "EMAIL" : "PHONE";
449	    }
450	
451	    /**
452	     * The owner's age band as of the {@link #getRegistrationDate() registrationDate}, derived
453	     * from {@link #getBirthDate() birthDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} for
454	     * 18 to 64 inclusive, {@code 'SENIOR'} for 65 and over. {@code null} when no birthDate is
455	     * supplied. Not persisted — derived from {@link #getBirthDate()} and
456	     * {@link #getRegistrationDate()}.
457	     */
458	    @Transient
459	    public String getAgeBand() {
460	        if (this.birthDate == null || this.registrationDate == null) {
461	            return null;
462	        }
463	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
464	        if (age < 18) {
465	            return "MINOR";
466	        }
467	        return age < 65 ? "ADULT" : "SENIOR";
468	    }
469	
470	    protected Set<Pet> getPetsInternal() {
471	        if (this.pets == null) {
472	            this.pets = new HashSet<>();
473	        }
474	        return this.pets;
475	    }
476	
477	    protected void setPetsInternal(Set<Pet> pets) {
478	        this.pets = pets;
479	    }
480	
481	    public List<Pet> getPets() {
482	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
483	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
484	        return Collections.unmodifiableList(sortedPets);
485	    }
486	
487	    public void setPets(List<Pet> pets) {
488	        this.pets = new HashSet<>(pets);
489	    }
490	
491	    public void addPet(Pet pet) {
492	        getPetsInternal().add(pet);
493	        pet.setOwner(this);
494	    }
495	
496	    /**
497	     * Return the Pet with the given name, or null if none found for this Owner.
498	     *
499	     * @param name to test
500	     * @return true if pet name is already in use
501	     */
502	    public Pet getPet(String name) {
503	        return getPet(name, false);
504	    }
505	
506	    /**
507	     * Return the Pet with the given name, or null if none found for this Owner.
508	     *
509	     * @param name to test
510	     * @return true if pet name is already in use
511	     */
512	    public Pet getPet(String name, boolean ignoreNew) {
513	        name = name.toLowerCase();
